n_terms":1,"professor":"Smith, Sandra Susan","professor_display":"Sandra Susan Smith","stem_group":null,"stem_school":null,"term":"Average","time_end":null,"time_start":null,"total_n_respondents":null,"workload_label":"Light","year":0,"year_range":"2022–2022"},{"bid_academic_year":"2025-2026","bid_capacity":null,"bid_clearing_price":1.0,"bid_n_bids":null,"concentration":"DPI","course_code":"DPI-805-M","course_code_base":"DPI-805-M","course_name":"Writing for Policy and Politics: Mastering Daily Communications","course_url":"https://www.hks.harvard.edu/courses/writing-policy-and-politics-mastering-daily-communications","description":"This intensive seven week course in effective writing focuses on the strategies and techniques behind great persuasive writing in both politics and policy. Students will master the essential life cycle of communications for anyone working in policy and politics, focusing on developing incisive questions, creating well-honed short form summaries, drafting press releases for media partners, writing to constituents, and crafting expert policy briefs.Every Communications Program course assumes a fluency with the English language. Attendance at first class required.","ever_bidding":true,"faculty_category":null,"faculty_title":null,"has_bidding":true,"has_eval":false,"id":"DPI-805-M||2025||Fall||Green, Alex","instructor_label":"No Data","is_average":false,"is_core":false,"is_stem":false,"last_bid_acad":"2025-2026","last_bid_capacity":null,"last_bid_n_bids":null,"last_bid_price":1.0,"last_bid_term":"Fall","location":null,"meeting_days":null,"metrics_pct":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":null,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"metrics_raw":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":1.0,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"n_respondents":null,"n_terms":1,"professor":"Green, Alex","professor_display":"Alex Green","stem_group":null,"stem_school":null,"term":"Fall","time_end":null,"time_start":null,"total_n_respondents":null,"workload_label":"No Data","year":2025,"year_range":null},{"bid_academic_year":"2025-2026","bid_capacity":null,"bid_clearing_price":149.0,"bid_n_bids":null,"concentration":"DPI","course_code":"DPI-820-M","course_code_base":"DPI-820-M","course_name":"Policy Memo Writing for Decision Makers","course_url":"https://www.hks.harvard.edu/courses/policy-memo-writing-decision-makers","description":"This is a course on writing persuasive policy memos, a skill relevant in the public sector and beyond. Students will learn to analyze policy problems, to make persuasive arguments, and to advise decision makers. Through practice opportunities and instructor and classmate feedback, students will learn to write with confidence and to build their professional writing tool kit. This course is open to writers of all levels: New policy writers will learn the norms of policy memos and how to write clearly and concisely. Experienced policy writers will find that the course enhances your ability to persuade and impact decision-making. All students will complete the module with excellent writing samples.Every Communications Program course assumes a fluency with the English language. Attendance at first class required.","ever_bidding":true,"faculty_category":null,"faculty_title":null,"has_bidding":true,"has_eval":false,"id":"DPI-820-M||2025||Fall||Brodsky, Lauren","instructor_label":"No Data","is_average":false,"is_core":false,"is_stem":false,"last_bid_acad":"2025-2026","last_bid_capacity":null,"last_bid_n_bids":null,"last_bid_price":149.0,"last_bid_term":"Fall","location":null,"meeting_days":null,"metrics_pct":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":null,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"metrics_raw":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":149.0,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"n_respondents":null,"n_terms":1,"professor":"Brodsky, Lauren","professor_display":"Lauren Brodsky","stem_group":null,"stem_school":null,"term":"Fall","time_end":null,"time_start":null,"total_n_respondents":null,"workload_label":"No Data","year":2025,"year_range":null},{"bid_academic_year":"2025-2026","bid_capacity":null,"bid_clearing_price":1.0,"bid_n_bids":null,"concentration":"DPI","course_code":"DPI-828-M","course_code_base":"DPI-828-M","course_name":"Policy Memo Writing and Presentations for Decision Makers","course_url":"https://www.hks.harvard.edu/courses/persuasive-policy-communication","description":"This module course will teach students both the theory and practice of persuasive policy writing. Course assignments will strengthen students’ ability to write professionally for public audiences across industries. Students will write policy blogs to learn how to tell compelling policy stories, and they will write an executive summary to learn how to distill and simplify information and data. Through readings and case studies, students will learn how to strengthen their use narrative, data, and evidence, and to craft strong counterarguments. Students will also learn how to write as a group, since policy writing is often created through collaboration. Students will complete the module with two individual writing samples, with the possibility of publication, and a broad sense of what strengthens persuasion in policymaking.Every Communications Program course assumes a fluency with the English language.","ever_bidding":true,"faculty_category":null,"faculty_title":null,"has_bidding":true,"has_eval":false,"id":"DPI-828-M||2025||Fall||Brodsky, Lauren","instructor_label":"No Data","is_average":false,"is_core":false,"is_stem":true,"last_bid_acad":"2025-2026","last_bid_capacity":null,"last_bid_n_bids":null,"last_bid_price":1.0,"last_bid_term":"Fall","location":null,"meeting_days":null,"metrics_pct":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":null,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"metrics_raw":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":1.0,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"n_respondents":null,"n_terms":1,"professor":"Brodsky, Lauren","professor_display":"Lauren Brodsky","stem_group":"B","stem_school":"HKS","term":"Fall","time_end":null,"time_start":null,"total_n_respondents":null,"workload_label":"No Data","year":2025,"year_range":null},{"bid_academic_year":"2025-2026","bid_capacity":null,"bid_clearing_price":21.0,"bid_n_bids":null,"concentration":"DPI","course_code":"DPI-830-M","course_code_base":"DPI-830-M","course_name":"Column and Opinion Writing Workshop","course_url":"https://www.hks.harvard.edu/courses/column-and-opinion-writing-workshop","description":"This writing workshop is designed to give students an understanding of the process of researching, writing, and revising columns with an emphasis on the importance of audience. While we will spend time distinguishing opinion columns as one type of column, we will also focus on several other types of columns. The class will be run as a writing workshop. Each student will be expected to write as well as provide feedback on other students’ writing throughout the J-Term course. Readings, writing assignments, in-class peer feedback, and class discussions will enable each student to execute a well-thought-out, well-written column. Students should come away from the course with a clear knowledge of how much preparation, work, revision, and understanding of readership go into good column writing. There will be both in-class and out-of-class assignments each day of the J-Term course for which deadlines are firm. The class starts on time and attendance at every class is mandatory.DPI-831M focuses entirely on op-ed writing, while DPI-830 focuses on all types of columns. Students cannot register for both DPI-831M and DPI-830 for credit. Every Communications Program course assumes a fluency with the English language. Attendance at first class required.","ever_bidding":true,"faculty_category":null,"faculty_title":null,"has_bidding":true,"has_eval":false,"id":"DPI-830-M||2026||January||Seglin, Jeffrey","instructor_label":"No Data","is_average":false,"is_core":false,"is_stem":false,"last_bid_acad":"2025-2026","last_bid_capacity":null,"last_bid_n_bids":null,"last_bid_price":21.0,"last_bid_term":"January","location":null,"meeting_days":null,"metrics_pct":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":null,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"metrics_raw":{"Assignments":null,"Availability":null,"Bid_N_Bids":null,"Bid_Price":21.0,"Course_Rating":null,"Discussion Diversity":null,"Discussions":null,"Diverse Perspectives":null,"Feedback":null,"Insights":null,"Instructor_Rating":null,"Readings":null,"Rigor":null,"Workload":null},"n_respondents":null,"n_terms":1,"professor":"Seglin, Jeffrey","professor_display":"Jeffrey Seglin","stem_group":null,"stem_school":null,"ter